    // Publishing here is part of the contract, not a fixture convenience: a
    // Starting a run is a Plates change: whether a slice is in flight is part
    // of what a plate can currently say about itself.
    CommandResult start_slice(std::optional<PlateId> plate, bool preempt) override
    {
        if (m_snapshot.slicing.running && !preempt)
            return CommandResult::failure(WorkspaceError::Busy,
                                          "A slice is already running. Wait for it, or ask again with preempt.");
        if (plate) {
            if (plate->session() != m_snapshot.session)
                return CommandResult::failure(WorkspaceError::StaleId, "That plate belongs to a project that is no longer open");
            const auto found = std::find_if(m_snapshot.plates.begin(), m_snapshot.plates.end(),
                                            [&plate](const WorkspacePlate& candidate) { return candidate.id == *plate; });
            if (found == m_snapshot.plates.end())
                return CommandResult::failure(WorkspaceError::NotFound, "That plate is not in the open project. Read workspace_inspect for the plate ids.");
        }
        ++slice_starts;
        // As OrcaSlicer decides inside the call that asks: its check refuses
        // the plate and records why, or every plate named is already sliced
        // and nothing runs, or a run begins.
        const auto named = [&plate](const WorkspacePlate& candidate) { return !plate || candidate.id == *plate; };
        WorkspacePlate* first = nullptr;
        bool all_sliced = !m_snapshot.plates.empty();
        for (WorkspacePlate& candidate : m_snapshot.plates)
            if (named(candidate)) {
                first = first ? first : &candidate;
                all_sliced = all_sliced && candidate.sliced;
            }
        if (refusal && first != nullptr) {
            record_failure_for_testing(*first, *refusal);
            return CommandResult::success();
        }
        if (all_sliced && !m_snapshot.slicing.running)
            return CommandResult::success();
        m_snapshot.slicing.running = true;
        m_snapshot.slicing.plate   = first ? std::optional<PlateId>(first->id) : std::optional<PlateId>();
        m_snapshot.slicing.percent = 0;
        if (first != nullptr)
